"""Compute the grounded extension of a finite argumentation framework
via least-fixed-point iteration of the characteristic (defense) operator."""
from __future__ import annotations
from typing import FrozenSet, Iterable, Set, Tuple

Attack = Tuple[str, str]


def grounded_extension(arguments: Iterable[str],
                       attacks: Iterable[Attack]) -> FrozenSet[str]:
    args: FrozenSet[str] = frozenset(arguments)
    atk: Set[Attack] = set(attacks)

    def defends(s: FrozenSet[str], a: str) -> bool:
        for b in args:
            if (b, a) in atk and not any((c, b) in atk for c in s):
                return False
        return True

    s: FrozenSet[str] = frozenset()
    while True:
        nxt = frozenset(a for a in args if defends(s, a))
        if nxt == s:
            return s
        s = nxt


if __name__ == "__main__":
    # c -> b -> a : grounded extension is {a, c}
    print(sorted(grounded_extension(
        ["a", "b", "c"], [("b", "a"), ("c", "b")])))

"""Empirically verify the Fundamental Lemma: for every admissible set S and
every argument a that S defends, the set S union {a} remains admissible."""
from __future__ import annotations
from itertools import chain, combinations
from typing import FrozenSet, Iterable, List, Set, Tuple

Attack = Tuple[str, str]


def powerset(items: Iterable[str]) -> List[FrozenSet[str]]:
    xs = list(items)
    return [frozenset(c) for c in chain.from_iterable(
        combinations(xs, k) for k in range(len(xs) + 1))]


def verify_fundamental_lemma(arguments: Iterable[str],
                             attacks: Iterable[Attack]) -> bool:
    args: FrozenSet[str] = frozenset(arguments)
    atk: Set[Attack] = set(attacks)

    def defends(s: FrozenSet[str], a: str) -> bool:
        return all(any((c, b) in atk for c in s)
                   for b in args if (b, a) in atk)

    def admissible(s: FrozenSet[str]) -> bool:
        cf = not any((a, b) in atk for a in s for b in s)
        return cf and all(defends(s, a) for a in s)

    for s in powerset(args):
        if not admissible(s):
            continue
        for a in (x for x in args if defends(s, x)):
            if not admissible(s | {a}):
                return False
    return True


if __name__ == "__main__":
    print(verify_fundamental_lemma(
        ["a", "b", "c", "d"],
        [("a", "b"), ("b", "a"), ("b", "c"), ("c", "d"), ("d", "d")]))

"""Enumerate and compare all four Dung semantics (complete, grounded,
preferred, stable) for a finite framework, confirming the inclusions
stable subset preferred subset complete and preferred = maximal complete."""
from __future__ import annotations
from itertools import chain, combinations
from typing import Dict, FrozenSet, Iterable, List, Set, Tuple

Attack = Tuple[str, str]


def all_semantics(arguments: Iterable[str],
                  attacks: Iterable[Attack]) -> Dict[str, List[FrozenSet[str]]]:
    args: FrozenSet[str] = frozenset(arguments)
    atk: Set[Attack] = set(attacks)

    def defends(s: FrozenSet[str], a: str) -> bool:
        return all(any((c, b) in atk for c in s)
                   for b in args if (b, a) in atk)

    def cf(s: FrozenSet[str]) -> bool:
        return not any((a, b) in atk for a in s for b in s)

    def adm(s: FrozenSet[str]) -> bool:
        return cf(s) and all(defends(s, a) for a in s)

    def F(s: FrozenSet[str]) -> FrozenSet[str]:
        return frozenset(a for a in args if defends(s, a))

    def comp(s: FrozenSet[str]) -> bool:
        return adm(s) and F(s) <= s

    def stab(s: FrozenSet[str]) -> bool:
        return cf(s) and all(any((b, a) in atk for b in s)
                             for a in args - s)

    ps = [frozenset(c) for c in chain.from_iterable(
        combinations(sorted(args), k) for k in range(len(args) + 1))]
    admissible = [s for s in ps if adm(s)]
    preferred = [s for s in admissible
                 if not any(s < t for t in admissible)]
    return {
        "complete": [s for s in ps if comp(s)],
        "preferred": preferred,
        "stable": [s for s in ps if stab(s)],
    }


if __name__ == "__main__":
    res = all_semantics(["a", "b"], [("a", "b"), ("b", "a")])
    for k, v in res.items():
        print(k, [sorted(s) for s in v])

