from __future__ import annotations
from typing import FrozenSet, Set, Tuple

Attack = Tuple[str, str]


def characteristic_operator(arguments: FrozenSet[str],
                            attacks: Set[Attack],
                            s: FrozenSet[str]) -> FrozenSet[str]:
    """Return F(S) = { a : S defends a }.

    S defends a iff every attacker b of a is counterattacked by some c in S.
    Runs in O(n * m) for n = |arguments|, m = |attacks|.
    """
    def defends(a: str) -> bool:
        for (b, target) in attacks:
            if target == a and not any((c, b) in attacks for c in s):
                return False
        return True
    return frozenset(a for a in arguments if defends(a))

from __future__ import annotations
from typing import FrozenSet, Set, Tuple

Attack = Tuple[str, str]


def grounded_fixpoint(arguments: FrozenSet[str],
                      attacks: Set[Attack]) -> FrozenSet[str]:
    """Least fixed point of the defense operator, started from empty set.

    Produces the grounded extension. Because F is monotone, the iterates
    form an increasing chain that stabilizes in at most |arguments| steps;
    total cost O(n^2 * m).
    """
    def F(s: FrozenSet[str]) -> FrozenSet[str]:
        def defends(a: str) -> bool:
            return all(any((c, b) in attacks for c in s)
                       for (b, t) in attacks if t == a)
        return frozenset(a for a in arguments if defends(a))

    s: FrozenSet[str] = frozenset()
    while True:
        nxt = F(s)
        if nxt == s:
            return s
        s = nxt

