"""Render the pointed poset of complete extensions as a Hasse diagram,
marking the grounded extension (bottom) and preferred extensions (top).
Requires networkx and matplotlib."""
from __future__ import annotations
from itertools import chain, combinations
from typing import FrozenSet, List, Set, Tuple
import networkx as nx
import matplotlib.pyplot as plt

Attack = Tuple[str, str]


def complete_extensions(args: FrozenSet[str],
                        atk: Set[Attack]) -> List[FrozenSet[str]]:
    def defends(s, a):
        return all(any((c, b) in atk for c in s)
                   for (b, t) in atk if t == a)

    def comp(s):
        cf = not any((x, y) in atk for x in s for y in s)
        F = frozenset(a for a in args if defends(s, a))
        return cf and all(defends(s, a) for a in s) and F <= s
    ps = [frozenset(c) for c in chain.from_iterable(
        combinations(sorted(args), k) for k in range(len(args) + 1))]
    return [s for s in ps if comp(s)]


def draw_hasse(arguments: List[str], attacks: List[Attack]) -> None:
    ce = complete_extensions(frozenset(arguments), set(attacks))
    g = nx.DiGraph()
    labels = {s: "{" + ",".join(sorted(s)) + "}" for s in ce}
    g.add_nodes_from(ce)
    for s in ce:
        for t in ce:
            if s < t and not any(s < u < t for u in ce):
                g.add_edge(s, t)
    pos = {s: (i, len(s)) for i, s in enumerate(sorted(ce, key=len))}
    nx.draw(g, pos, labels=labels, node_color="#90CAF9", node_size=1800,
            font_size=10, edgecolors="black", arrows=False)
    plt.title("Hasse diagram of complete extensions (bottom = grounded)")
    plt.tight_layout()
    plt.savefig("extension_poset.png", dpi=150)
    print("wrote extension_poset.png")


if __name__ == "__main__":
    draw_hasse(["a", "b", "c", "d"],
               [("a", "b"), ("b", "a"), ("b", "c"), ("c", "d"), ("d", "d")])
